-- PostgreSQL: one atomic statement. Requires an existing users.id = 1.
-- Design: Wide left career column with pale sage right sidebar and forest green headings.
-- All profile details, organizations, and accomplishments are fictional.
-- Each execution creates a new resume; IDs are generated by the database.
WITH
content AS (
    SELECT $resume_data$
[
{"label": "Header", "type": "header", "columnPosition": 0, "showHeading": false, "styling": {}, "layout": {"display": "grid", "grid": {"columns": 1}, "padding": {"top": "0rem", "bottom": "0rem"}}, "value": [{"type": "heading", "textAlign": "left", "children": [{"text": "HEADER", "bold": true, "fontSizeOffset": 0, "lineHeightOffset": 0, "color": "#315C48"}]}], "subsections": [{"label": "JOHN DOE", "fields": [{"label": "Name", "value": [{"type": "paragraph", "label": "Name", "children": [{"text": "JOHN DOE", "fontSizeOffset": 20, "lineHeightOffset": 0, "bold": true, "color": "#315C48"}], "textAlign": "left"}]}, {"label": "Title", "value": [{"type": "paragraph", "label": "Title", "children": [{"text": "SUSTAINABILITY PROGRAM MANAGER", "fontSizeOffset": 1, "lineHeightOffset": 0, "color": "#315C48"}], "textAlign": "left"}]}, {"label": "Contact", "value": [{"type": "paragraph", "label": "Contact", "children": [{"text": "Seattle, WA", "fontSizeOffset": -1, "lineHeightOffset": 0, "color": "#315C48"}], "textAlign": "left"}]}]}]},
{"label": "Profile", "type": "summary", "columnPosition": 0, "showHeading": true, "styling": {}, "layout": {"display": "grid", "grid": {"columns": 1}, "padding": {"top": "0rem", "bottom": "0rem"}}, "value": [{"type": "heading", "textAlign": "left", "children": [{"text": "PROFILE", "bold": true, "fontSizeOffset": 0, "lineHeightOffset": 0, "color": "#315C48"}]}], "subsections": [{"label": "Profile", "fields": [{"label": "Summary", "value": [{"type": "paragraph", "label": "Summary", "children": [{"text": "Program manager with 6 years of experience turning sustainability goals into practical projects. Brings teams together around measurable plans, reliable reporting, and lasting improvements.", "fontSizeOffset": 0, "lineHeightOffset": 0}]}]}]}]},
{"label": "Experience", "type": "workHistory", "columnPosition": 0, "showHeading": true, "styling": {}, "layout": {"display": "grid", "grid": {"columns": 1}, "padding": {"top": "0rem", "bottom": "0rem"}}, "value": [{"type": "heading", "textAlign": "left", "children": [{"text": "EXPERIENCE", "bold": true, "fontSizeOffset": 0, "lineHeightOffset": 0, "color": "#315C48"}]}], "subsections": [{"label": "Evergreen Works", "fields": [{"label": "Job Title", "value": [{"type": "paragraph", "label": "Job Title", "children": [{"text": "Sustainability Program Manager", "fontSizeOffset": 1, "lineHeightOffset": 0, "bold": true}]}]}, {"label": "Company", "value": [{"type": "paragraph", "label": "Company", "children": [{"text": "Evergreen Works | 2023 - Present", "fontSizeOffset": -0.5, "lineHeightOffset": 0, "color": "#59675F"}]}]}, {"label": "Description", "value": [{"type": "unordered-list", "children": [{"type": "list-item", "children": [{"text": "Coordinated energy and waste initiatives across 8 sites, reducing annual electricity use by 19%.", "fontSizeOffset": 0, "lineHeightOffset": 0}]}, {"type": "list-item", "children": [{"text": "Built a monthly scorecard that gave 25 site leads a shared view of progress.", "fontSizeOffset": 0, "lineHeightOffset": 0}]}, {"type": "list-item", "children": [{"text": "Piloted a supplier review process covering 70% of annual purchasing.", "fontSizeOffset": 0, "lineHeightOffset": 0}]}]}]}]}, {"label": "Fieldstone Partners", "fields": [{"label": "Job Title", "value": [{"type": "paragraph", "label": "Job Title", "children": [{"text": "Program Coordinator", "fontSizeOffset": 1, "lineHeightOffset": 0, "bold": true}]}]}, {"label": "Company", "value": [{"type": "paragraph", "label": "Company", "children": [{"text": "Fieldstone Partners | 2020 - 2023", "fontSizeOffset": -0.5, "lineHeightOffset": 0, "color": "#59675F"}]}]}, {"label": "Description", "value": [{"type": "unordered-list", "children": [{"type": "list-item", "children": [{"text": "Organized 14 community projects with 300 volunteers and maintained a 95% event satisfaction score.", "fontSizeOffset": 0, "lineHeightOffset": 0}]}, {"type": "list-item", "children": [{"text": "Streamlined project tracking, saving team leads 5 hours each week.", "fontSizeOffset": 0, "lineHeightOffset": 0}]}]}]}]}]},
{"label": "Selected Project", "type": "projects", "columnPosition": 0, "showHeading": true, "styling": {}, "layout": {"display": "grid", "grid": {"columns": 1}, "padding": {"top": "0rem", "bottom": "0rem"}}, "value": [{"type": "heading", "textAlign": "left", "children": [{"text": "SELECTED PROJECT", "bold": true, "fontSizeOffset": 0, "lineHeightOffset": 0, "color": "#315C48"}]}], "subsections": [{"label": "Reuse Network", "fields": [{"label": "Project Title", "value": [{"type": "paragraph", "label": "Project Title", "children": [{"text": "Workplace Reuse Network", "fontSizeOffset": 1, "lineHeightOffset": 0, "bold": true}]}]}, {"label": "Description", "value": [{"type": "paragraph", "label": "Description", "children": [{"text": "Created a shared inventory and transfer process for surplus office equipment. Redirected 420 items to internal teams and community partners in the first year.", "fontSizeOffset": 0, "lineHeightOffset": 0}]}]}]}]},
{"label": "Contact", "type": "contact", "columnPosition": 1, "showHeading": true, "styling": {"backgroundColor": "#EDF3EE", "color": "#293E32"}, "layout": {"display": "grid", "grid": {"columns": 1}, "padding": {"top": "0rem", "bottom": "0rem"}}, "value": [{"type": "heading", "textAlign": "left", "children": [{"text": "CONTACT", "bold": true, "fontSizeOffset": 0, "lineHeightOffset": 0, "color": "#315C48"}]}], "subsections": [{"label": "Contact", "fields": [{"label": "Email", "value": [{"type": "paragraph", "label": "Email", "children": [{"text": "john.doe@example.com", "fontSizeOffset": -0.5, "lineHeightOffset": 0}]}]}, {"label": "Phone", "value": [{"type": "paragraph", "label": "Phone", "children": [{"text": "(206) 555-0164", "fontSizeOffset": 0, "lineHeightOffset": 0}]}]}, {"label": "Website", "value": [{"type": "paragraph", "label": "Website", "children": [{"text": "johndoe.example.com", "fontSizeOffset": -0.5, "lineHeightOffset": 0}]}]}]}]},
{"label": "Strengths", "type": "skills", "columnPosition": 1, "showHeading": true, "styling": {"backgroundColor": "#EDF3EE", "color": "#293E32"}, "layout": {"display": "grid", "grid": {"columns": 1}, "padding": {"top": "0rem", "bottom": "0rem"}}, "value": [{"type": "heading", "textAlign": "left", "children": [{"text": "STRENGTHS", "bold": true, "fontSizeOffset": 0, "lineHeightOffset": 0, "color": "#315C48"}]}], "subsections": [{"label": "Strengths", "fields": [{"label": "Planning", "value": [{"type": "paragraph", "label": "Planning", "children": [{"text": "Program planning", "fontSizeOffset": 0, "lineHeightOffset": 0}]}]}, {"label": "Reporting", "value": [{"type": "paragraph", "label": "Reporting", "children": [{"text": "Impact reporting", "fontSizeOffset": 0, "lineHeightOffset": 0}]}]}, {"label": "Engagement", "value": [{"type": "paragraph", "label": "Engagement", "children": [{"text": "Community engagement", "fontSizeOffset": 0, "lineHeightOffset": 0}]}]}, {"label": "Vendors", "value": [{"type": "paragraph", "label": "Vendors", "children": [{"text": "Supplier coordination", "fontSizeOffset": 0, "lineHeightOffset": 0}]}]}, {"label": "Analysis", "value": [{"type": "paragraph", "label": "Analysis", "children": [{"text": "Data analysis", "fontSizeOffset": 0, "lineHeightOffset": 0}]}]}]}, {"label": "Tools", "fields": [{"label": "Tools", "value": [{"type": "paragraph", "label": "Tools", "children": [{"text": "Excel / Power BI", "fontSizeOffset": 0, "lineHeightOffset": 0, "bold": true}]}]}, {"label": "Workflow", "value": [{"type": "paragraph", "label": "Workflow", "children": [{"text": "Airtable / Miro", "fontSizeOffset": 0, "lineHeightOffset": 0}]}]}]}]},
{"label": "Education", "type": "education", "columnPosition": 1, "showHeading": true, "styling": {"backgroundColor": "#EDF3EE", "color": "#293E32"}, "layout": {"display": "grid", "grid": {"columns": 1}, "padding": {"top": "0rem", "bottom": "0rem"}}, "value": [{"type": "heading", "textAlign": "left", "children": [{"text": "EDUCATION", "bold": true, "fontSizeOffset": 0, "lineHeightOffset": 0, "color": "#315C48"}]}], "subsections": [{"label": "Fern Valley College", "fields": [{"label": "Degree", "value": [{"type": "paragraph", "label": "Degree", "children": [{"text": "B.S. Environmental Studies", "fontSizeOffset": 0, "lineHeightOffset": 0, "bold": true}]}]}, {"label": "School", "value": [{"type": "paragraph", "label": "School", "children": [{"text": "Fern Valley College", "fontSizeOffset": 0, "lineHeightOffset": 0}]}]}, {"label": "Dates", "value": [{"type": "paragraph", "label": "Dates", "children": [{"text": "2016 - 2020", "fontSizeOffset": -0.5, "lineHeightOffset": 0}]}]}]}]},
{"label": "Community", "type": "custom", "columnPosition": 1, "showHeading": true, "styling": {"backgroundColor": "#EDF3EE", "color": "#293E32"}, "layout": {"display": "grid", "grid": {"columns": 1}, "padding": {"top": "0rem", "bottom": "0rem"}}, "value": [{"type": "heading", "textAlign": "left", "children": [{"text": "COMMUNITY", "bold": true, "fontSizeOffset": 0, "lineHeightOffset": 0, "color": "#315C48"}]}], "subsections": [{"label": "Volunteer", "fields": [{"label": "Role", "value": [{"type": "paragraph", "label": "Role", "children": [{"text": "Volunteer Team Lead", "fontSizeOffset": 0, "lineHeightOffset": 0, "bold": true}]}]}, {"label": "Organization", "value": [{"type": "paragraph", "label": "Organization", "children": [{"text": "Neighborhood Greenways", "fontSizeOffset": 0, "lineHeightOffset": 0}]}]}, {"label": "Dates", "value": [{"type": "paragraph", "label": "Dates", "children": [{"text": "2021 - Present", "fontSizeOffset": -0.5, "lineHeightOffset": 0}]}]}, {"label": "Description", "value": [{"type": "paragraph", "label": "Description", "children": [{"text": "Organizes seasonal cleanups and neighborhood planting days.", "fontSizeOffset": 0, "lineHeightOffset": 0}]}]}]}]}
]
$resume_data$::jsonb AS sections
),
new_resume AS (
    INSERT INTO resumes (user_id, title, styling, layout, created_at, updated_at)
    VALUES (
        1,
        'John Doe - Sage Portfolio',
        '{"display": "flex", "fontFamily": "Arial, Helvetica, sans-serif", "fontSize": "12.5px", "lineHeight": 1.3, "color": "#28323C", "backgroundColor": "#FFFFFF"}'::json,
        '{"padding": {"top": "1.6rem", "right": "1.6rem", "bottom": "1.6rem", "left": "1.6rem"}, "gap": {"horizontal": "0.35rem", "vertical": "0.4rem", "subsection": "0.65rem", "field": "0.13rem"}}'::json,
        CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
    )
    RETURNING id, title
),
new_columns AS (
    INSERT INTO columns (resume_id, position, styling, layout, created_at, updated_at)
    SELECT r.id, c.position, '{}'::json, c.layout,
        CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
    FROM new_resume r
    CROSS JOIN (VALUES
        (0, '{"width": {"auto": false, "value": "67%"}, "padding": {"top": "0rem", "bottom": "0rem", "left": "1rem", "right": "1rem"}}'::json),
        (1, '{"width": {"auto": false, "value": "33%"}, "padding": {"top": "0rem", "bottom": "0rem", "left": "1rem", "right": "1rem"}}'::json)
    ) AS c(position, layout)
    RETURNING id, position
),
section_data AS (
    SELECT (s.ordinality - 1)::integer AS position, s.item
    FROM content
    CROSS JOIN LATERAL jsonb_array_elements(content.sections)
        WITH ORDINALITY AS s(item, ordinality)
),
new_sections AS (
    INSERT INTO sections (
        column_id, label, type, value, show_heading, position,
        styling, layout, created_at, updated_at
    )
    SELECT c.id, s.item->>'label', s.item->>'type',
        (s.item->'value')::json,
        (s.item->>'showHeading')::boolean, s.position,
        (s.item->'styling')::json, (s.item->'layout')::json,
        CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
    FROM section_data s
    JOIN new_columns c ON c.position = (s.item->>'columnPosition')::integer
    RETURNING id, position
),
subsection_data AS (
    SELECT s.id AS section_id, (sub.ordinality - 1)::integer AS position, sub.item
    FROM new_sections s
    JOIN section_data d ON d.position = s.position
    CROSS JOIN LATERAL jsonb_array_elements(d.item->'subsections')
        WITH ORDINALITY AS sub(item, ordinality)
),
new_subsections AS (
    INSERT INTO subsections (
        section_id, label, type, position, styling, layout, created_at, updated_at
    )
    SELECT d.section_id, d.item->>'label', s.item->>'type', d.position,
        '{"fontSizeOffset":0,"lineHeightOffset":0}'::json, '{}'::json,
        CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
    FROM subsection_data d
    JOIN new_sections n ON n.id = d.section_id
    JOIN section_data s ON s.position = n.position
    RETURNING id, section_id, position
),
new_fields AS (
    INSERT INTO fields (
        subsection_id, label, value, position, styling, layout, created_at, updated_at
    )
    SELECT sub.id, f.item->>'label', (f.item->'value')::json,
        (f.ordinality - 1)::integer,
        '{"fontSizeOffset":0,"lineHeightOffset":0}'::json, '{}'::json,
        CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
    FROM new_subsections sub
    JOIN subsection_data d ON d.section_id = sub.section_id AND d.position = sub.position
    CROSS JOIN LATERAL jsonb_array_elements(d.item->'fields')
        WITH ORDINALITY AS f(item, ordinality)
    RETURNING id
)
SELECT id AS resume_id, title, (SELECT count(*) FROM new_fields) AS fields_created
FROM new_resume;
